-- CrowRules Podcasting Community Circles
-- Project: cevylpnoexugwgygvtgu
create table if not exists public.podcast_community_circles(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,name text not null check(char_length(name) between 3 and 70),description text not null default '' check(char_length(description)<=500),category text not null default 'General' check(category in ('General','Entertainment','Sports','Storytelling','Local & PNW','Music','Film & TV','Creators','Technology','Other')),is_public boolean not null default true,is_featured boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists podcast_community_circles_discovery_idx on public.podcast_community_circles(is_public,is_featured desc,updated_at desc);
create index if not exists podcast_community_circles_owner_idx on public.podcast_community_circles(owner_id);
create table if not exists public.podcast_community_circle_members(circle_id uuid not null references public.podcast_community_circles(id) on delete cascade,member_id uuid not null references auth.users(id) on delete cascade,role text not null default 'member' check(role in ('owner','moderator','member')),joined_at timestamptz not null default now(),primary key(circle_id,member_id));
create index if not exists podcast_community_circle_members_member_idx on public.podcast_community_circle_members(member_id,joined_at desc);
create table if not exists public.podcast_community_circle_posts(id uuid primary key default gen_random_uuid(),circle_id uuid not null references public.podcast_community_circles(id) on delete cascade,author_id uuid not null references auth.users(id) on delete cascade,body text not null check(char_length(body) between 1 and 3000),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists podcast_community_circle_posts_feed_idx on public.podcast_community_circle_posts(circle_id,created_at desc);
create table if not exists public.podcast_community_circle_replies(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.podcast_community_circle_posts(id) on delete cascade,circle_id uuid not null references public.podcast_community_circles(id) on delete cascade,author_id uuid not null references auth.users(id) on delete cascade,body text not null check(char_length(body) between 1 and 1500),created_at timestamptz not null default now());
create index if not exists podcast_community_circle_replies_post_idx on public.podcast_community_circle_replies(post_id,created_at asc);
alter table public.podcast_community_circles enable row level security; alter table public.podcast_community_circle_members enable row level security; alter table public.podcast_community_circle_posts enable row level security; alter table public.podcast_community_circle_replies enable row level security;
drop policy if exists "Discover public circles and view private circles you own or joined" on public.podcast_community_circles;
create policy "Discover public circles and view private circles you own or joined" on public.podcast_community_circles for select to authenticated using(is_public or owner_id=(select auth.uid()) or public.crowrules_is_admin() or exists(select 1 from public.podcast_community_circle_members m where m.circle_id=id and m.member_id=(select auth.uid())));
drop policy if exists "Members can create circles they own" on public.podcast_community_circles;
create policy "Members can create circles they own" on public.podcast_community_circles for insert to authenticated with check(owner_id=(select auth.uid()) and is_featured=false);
drop policy if exists "Circle owners can update their circles" on public.podcast_community_circles;
create policy "Circle owners can update their circles" on public.podcast_community_circles for update to authenticated using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()) and is_featured=false);
drop policy if exists "Podcast admins can feature circles" on public.podcast_community_circles;
create policy "Podcast admins can feature circles" on public.podcast_community_circles for update to authenticated using(public.crowrules_is_admin()) with check(public.crowrules_is_admin());
drop policy if exists "Members can see their own circle memberships and owners can manage rosters" on public.podcast_community_circle_members;
create policy "Members can see their own circle memberships and owners can manage rosters" on public.podcast_community_circle_members for select to authenticated using(member_id=(select auth.uid()) or public.crowrules_is_admin() or exists(select 1 from public.podcast_community_circles c where c.id=circle_id and c.owner_id=(select auth.uid())));
drop policy if exists "Members can join public circles and owners can add themselves" on public.podcast_community_circle_members;
create policy "Members can join public circles and owners can add themselves" on public.podcast_community_circle_members for insert to authenticated with check(member_id=(select auth.uid()) and ((role='member' and exists(select 1 from public.podcast_community_circles c where c.id=circle_id and c.is_public)) or (role='owner' and exists(select 1 from public.podcast_community_circles c where c.id=circle_id and c.owner_id=(select auth.uid())))));
drop policy if exists "Members can leave and owners can remove members" on public.podcast_community_circle_members;
create policy "Members can leave and owners can remove members" on public.podcast_community_circle_members for delete to authenticated using((member_id=(select auth.uid()) and role<>'owner') or public.crowrules_is_admin() or exists(select 1 from public.podcast_community_circles c where c.id=circle_id and c.owner_id=(select auth.uid()) and member_id<>c.owner_id));
drop policy if exists "Circle owners can promote members to moderators" on public.podcast_community_circle_members;
create policy "Circle owners can promote members to moderators" on public.podcast_community_circle_members for update to authenticated using(public.crowrules_is_admin() or exists(select 1 from public.podcast_community_circles c where c.id=circle_id and c.owner_id=(select auth.uid()))) with check(role in ('moderator','member') and (public.crowrules_is_admin() or exists(select 1 from public.podcast_community_circles c where c.id=circle_id and c.owner_id=(select auth.uid()))));
drop policy if exists "Circle posts are visible to public or joined members" on public.podcast_community_circle_posts;
create policy "Circle posts are visible to public or joined members" on public.podcast_community_circle_posts for select to authenticated using(exists(select 1 from public.podcast_community_circles c where c.id=circle_id and (c.is_public or c.owner_id=(select auth.uid()) or public.crowrules_is_admin() or exists(select 1 from public.podcast_community_circle_members m where m.circle_id=c.id and m.member_id=(select auth.uid())))));
drop policy if exists "Circle members can publish posts" on public.podcast_community_circle_posts;
create policy "Circle members can publish posts" on public.podcast_community_circle_posts for insert to authenticated with check(author_id=(select auth.uid()) and exists(select 1 from public.podcast_community_circle_members m where m.circle_id=circle_id and m.member_id=(select auth.uid())));
drop policy if exists "Authors and circle owners can update posts" on public.podcast_community_circle_posts;
create policy "Authors and circle owners can update posts" on public.podcast_community_circle_posts for update to authenticated using(author_id=(select auth.uid()) or public.crowrules_is_admin() or exists(select 1 from public.podcast_community_circles c where c.id=circle_id and c.owner_id=(select auth.uid()))) with check(author_id=(select auth.uid()) or public.crowrules_is_admin() or exists(select 1 from public.podcast_community_circles c where c.id=circle_id and c.owner_id=(select auth.uid())));
drop policy if exists "Authors and circle owners can delete posts" on public.podcast_community_circle_posts;
create policy "Authors and circle owners can delete posts" on public.podcast_community_circle_posts for delete to authenticated using(author_id=(select auth.uid()) or public.crowrules_is_admin() or exists(select 1 from public.podcast_community_circles c where c.id=circle_id and c.owner_id=(select auth.uid())));
drop policy if exists "Replies visible wherever the parent post is visible" on public.podcast_community_circle_replies;
create policy "Replies visible wherever the parent post is visible" on public.podcast_community_circle_replies for select to authenticated using(exists(select 1 from public.podcast_community_circle_posts p where p.id=post_id and p.circle_id=circle_id));
drop policy if exists "Circle members can reply" on public.podcast_community_circle_replies;
create policy "Circle members can reply" on public.podcast_community_circle_replies for insert to authenticated with check(author_id=(select auth.uid()) and exists(select 1 from public.podcast_community_circle_members m where m.circle_id=circle_id and m.member_id=(select auth.uid())) and exists(select 1 from public.podcast_community_circle_posts p where p.id=post_id and p.circle_id=circle_id));
drop policy if exists "Reply authors and circle owners can delete replies" on public.podcast_community_circle_replies;
create policy "Reply authors and circle owners can delete replies" on public.podcast_community_circle_replies for delete to authenticated using(author_id=(select auth.uid()) or public.crowrules_is_admin() or exists(select 1 from public.podcast_community_circles c where c.id=circle_id and c.owner_id=(select auth.uid())));
revoke all on public.podcast_community_circles,public.podcast_community_circle_members,public.podcast_community_circle_posts,public.podcast_community_circle_replies from anon,public;
grant select,insert,update on public.podcast_community_circles to authenticated;
grant select,insert,update,delete on public.podcast_community_circle_members to authenticated;
grant select,insert,update,delete on public.podcast_community_circle_posts to authenticated;
grant select,insert,delete on public.podcast_community_circle_replies to authenticated;

-- Management Center extension (rules, pinned discussions, invitations, moderator permissions)
alter table public.podcast_community_circles add column if not exists community_rules text not null default '' check(char_length(community_rules)<=3000);
alter table public.podcast_community_circles add column if not exists pinned_post_id uuid null references public.podcast_community_circle_posts(id) on delete set null;
create table if not exists public.podcast_community_circle_invites(id uuid primary key default gen_random_uuid(),circle_id uuid not null references public.podcast_community_circles(id) on delete cascade,inviter_id uuid not null references auth.users(id) on delete cascade,invitee_id uuid not null references auth.users(id) on delete cascade,status text not null default 'pending' check(status in ('pending','accepted','declined','cancelled')),created_at timestamptz not null default now(),responded_at timestamptz,unique(circle_id,invitee_id));
create index if not exists podcast_circle_invites_invitee_idx on public.podcast_community_circle_invites(invitee_id,status,created_at desc);
alter table public.podcast_community_circle_invites enable row level security;
revoke all on public.podcast_community_circle_invites from anon,public;
grant select,insert,update,delete on public.podcast_community_circle_invites to authenticated;
drop policy if exists "Circle owners manage invitations" on public.podcast_community_circle_invites;
create policy "Circle owners manage invitations" on public.podcast_community_circle_invites for select to authenticated using(inviter_id=(select auth.uid()) or invitee_id=(select auth.uid()) or public.crowrules_is_admin() or exists(select 1 from public.podcast_community_circles c where c.id=circle_id and c.owner_id=(select auth.uid())));
drop policy if exists "Owners can invite members" on public.podcast_community_circle_invites;
create policy "Owners can invite members" on public.podcast_community_circle_invites for insert to authenticated with check(inviter_id=(select auth.uid()) and invitee_id<>(select auth.uid()) and exists(select 1 from public.podcast_community_circles c where c.id=circle_id and c.owner_id=(select auth.uid())));
drop policy if exists "Invitees can respond" on public.podcast_community_circle_invites;
create policy "Invitees can respond" on public.podcast_community_circle_invites for update to authenticated using(invitee_id=(select auth.uid()) and status='pending') with check(invitee_id=(select auth.uid()) and status in ('accepted','declined'));
drop policy if exists "Owners can cancel invitations" on public.podcast_community_circle_invites;
create policy "Owners can cancel invitations" on public.podcast_community_circle_invites for delete to authenticated using(inviter_id=(select auth.uid()) or public.crowrules_is_admin() or exists(select 1 from public.podcast_community_circles c where c.id=circle_id and c.owner_id=(select auth.uid())));
drop policy if exists "Discover public circles and view private circles you own or joined" on public.podcast_community_circles;
create policy "Discover public circles and view private circles you own or joined" on public.podcast_community_circles for select to authenticated using(is_public or owner_id=(select auth.uid()) or public.crowrules_is_admin() or exists(select 1 from public.podcast_community_circle_members m where m.circle_id=id and m.member_id=(select auth.uid())) or exists(select 1 from public.podcast_community_circle_invites i where i.circle_id=id and i.invitee_id=(select auth.uid()) and i.status='pending'));
drop policy if exists "Members can join public circles and owners can add themselves" on public.podcast_community_circle_members;
create policy "Members can join public circles and owners can add themselves" on public.podcast_community_circle_members for insert to authenticated with check(member_id=(select auth.uid()) and ((role='member' and (exists(select 1 from public.podcast_community_circles c where c.id=circle_id and c.is_public) or exists(select 1 from public.podcast_community_circle_invites i where i.circle_id=circle_id and i.invitee_id=(select auth.uid()) and i.status='accepted'))) or (role='owner' and exists(select 1 from public.podcast_community_circles c where c.id=circle_id and c.owner_id=(select auth.uid())))));
drop policy if exists "Members can leave and owners can remove members" on public.podcast_community_circle_members;
create policy "Members can leave and owners can remove members" on public.podcast_community_circle_members for delete to authenticated using((member_id=(select auth.uid()) and role<>'owner') or public.crowrules_is_admin() or exists(select 1 from public.podcast_community_circles c where c.id=circle_id and (c.owner_id=(select auth.uid()) or exists(select 1 from public.podcast_community_circle_members m where m.circle_id=c.id and m.member_id=(select auth.uid()) and m.role='moderator')) and member_id<>c.owner_id));
drop policy if exists "Authors and circle owners can delete posts" on public.podcast_community_circle_posts;
create policy "Authors and circle owners can delete posts" on public.podcast_community_circle_posts for delete to authenticated using(author_id=(select auth.uid()) or public.crowrules_is_admin() or exists(select 1 from public.podcast_community_circles c where c.id=circle_id and (c.owner_id=(select auth.uid()) or exists(select 1 from public.podcast_community_circle_members m where m.circle_id=c.id and m.member_id=(select auth.uid()) and m.role='moderator'))));
drop policy if exists "Reply authors and circle owners can delete replies" on public.podcast_community_circle_replies;
create policy "Reply authors and circle owners can delete replies" on public.podcast_community_circle_replies for delete to authenticated using(author_id=(select auth.uid()) or public.crowrules_is_admin() or exists(select 1 from public.podcast_community_circles c where c.id=circle_id and (c.owner_id=(select auth.uid()) or exists(select 1 from public.podcast_community_circle_members m where m.circle_id=c.id and m.member_id=(select auth.uid()) and m.role='moderator'))));
